import{_ as o,r as t,o as n,c as s,e as a,a as c,s as l}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"Child Themes - October CMS - 3.x","titleTemplate":false,"description":"Override a theme by creating a child version.","frontmatter":{"subtitle":"Override a theme by creating a child version."},"headers":[{"level":2,"title":"Theme Lock File","slug":"theme-lock-file","link":"#theme-lock-file","children":[]},{"level":2,"title":"Creating a New Child Theme","slug":"creating-a-new-child-theme","link":"#creating-a-new-child-theme","children":[]}],"relativePath":"3.x/cms/themes/child-themes.md","filePath":"3.x/cms/themes/child-themes.md"}'),d={name:"3.x/cms/themes/child-themes.md"};function r(m,e,p,g,f,u){const i=t("pre-heading"),h=t("post-heading");return n(),s("div",null,[a(i),e[0]||(e[0]=c("h1",null,"Child Themes",-1)),a(h),e[1]||(e[1]=l(`<p>Child themes allow for the possibility of theme inheritence. A good use of this is when you have a third party theme or a theme that is in read-only mode. A child theme will reference a parent and use it as a fallback source.</p><p>If a page named <code>home.htm</code> exists in the parent theme but not the child, it treats it the same as if it did; the URL is active, and you can open the page like normal. When saving the page in the backend area, a new file is created in the child theme to override the contents.</p><p>To enable this feature for a theme, navigate to <strong>Settings → Frontend Theme</strong>, select <strong>Edit Properties</strong> and select a parent from the <strong>Parent Theme</strong> dropdown list.</p><h2 id="theme-lock-file"><a href="#theme-lock-file" class="header-anchor">#</a> Theme Lock File</h2><p>When installing a theme from a third party using Composer, it is important to note that when the theme is updated, all the files can be overwritten. This could result in any customizations made to the theme being lost. As a safety mechanism, a file called <code>.themelock</code> is included to protect a theme from any changes that may be lost during a system update.</p><p>When the file <code>.themelock</code> is present in the theme directory:</p><ul><li>The theme can only be selected as a parent theme</li><li>The theme does not appear in the backend UI</li><li>The theme cannot be selected as active</li></ul><h2 id="creating-a-new-child-theme"><a href="#creating-a-new-child-theme" class="header-anchor">#</a> Creating a New Child Theme</h2><p>The <code>theme:copy</code> command can be used to create new themes, including child themes. The following command creates a new theme called <code>demo-copy</code> from the source theme <code>demo</code> by copying the directory and its contents. The <code>.themelock</code> file will be removed during this process.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:copy demo demo-copy
</code></pre></div><p>To create a child theme that inherits the parent theme, specify the <code>--child</code> option.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:copy demo demo-child <span class="token parameter variable">--child</span>
</code></pre></div>`,12))])}const y=o(d,[["render",r]]);export{_ as __pageData,y as default};
